#include "../../04-图论/最大团与极大团.cpp"
int main(){mt19937 r(21);for(int t=0;t<250;t++){int n=r()%13;vector<bitset<200>> g(n);vector<unsigned long long> b(n);for(int i=0;i<n;i++)for(int j=0;j<i;j++)if(r()%2)g[i][j]=g[j][i]=1,b[i]|=1ULL<<j,b[j]|=1ULL<<i;int best=0;set<unsigned long long> want;for(int s=0;s<(1<<n);s++){bool ok=true,extend=false;for(int i=0;i<n;i++)if(s>>i&1)ok&=((b[i]&(unsigned)s)==((unsigned)s^(1U<<i)));if(!ok)continue;best=max(best,__builtin_popcount((unsigned)s));for(int i=0;i<n;i++)if(!(s>>i&1)&&(b[i]&(unsigned)s)==(unsigned)s)extend=true;if(!extend)want.insert(s);}auto ans=MaximumClique(g).solve();assert((int)ans.size()==best);set<unsigned long long> got;maximal_cliques(b,[&](auto s){got.insert(s);});assert(got==want);}}
